# One-line version of CreateLocalAdmin.ps1 — paste into an elevated PowerShell.
# (Preserved deliberately as a single statement to survive copy/paste via remote tools.)
# Prompts: create admin? -> username (default Admin) -> password (no default, must be non-empty) -> enable RDP?
$u = Read-Host 'Create local admin? (Y/N)'; if ($u -eq 'Y') { $n = Read-Host 'Username (Default: Admin)'; if (-not $n) { $n = 'Admin' }; if (Get-LocalUser -Name $n -ErrorAction SilentlyContinue) { Write-Host "User '$n' already exists." -ForegroundColor Yellow } else { do { $p = Read-Host "Password for '$n'" -AsSecureString } while ($p.Length -eq 0); New-LocalUser -Name $n -Password $p -FullName 'Local Administrator' -Description 'Local admin account' -UserMayNotChangePassword -PasswordNeverExpires | Out-Null; Add-LocalGroupMember -Group 'Administrators' -Member $n; Write-Host "Created '$n' and added to Administrators."; if ((Read-Host 'Enable RDP? (Y/N)') -eq 'Y') { Set-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Control\Terminal Server' -Name 'fDenyTSConnections' -Value 0; Enable-NetFirewallRule -DisplayGroup 'Remote Desktop'; Add-LocalGroupMember -Group 'Remote Desktop Users' -Member $n -ErrorAction SilentlyContinue; Write-Host 'RDP enabled.' } } }
